using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "StarRequirementAction", menuName = "Data/Battle/Battle Actions/Orion/StarRequirement Action")]
public class StarRequirementAction : BattleAction
{
	[Header("Star Ability")]
	[SerializeField]
	protected StarAbilityReference starAbilityReference;

	[SerializeField]
	protected StarAbility starAbilityToUse;

	public StarAbility StarAbilityToUse => starAbilityToUse;

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		return starAbilityReference.Value == starAbilityToUse;
	}
}
